import { csvCell, csvNumber, toCSV } from './csv.mjs';

const LINE = /^(\d+(?:\.\d+)?)\s*(?:x|\*|,)?\s*(\d+)?$/i;

function parseLengthList(text, label) {
  const lengths = [];
  for (const [index, line] of String(text).split(/\r?\n/).entries()) {
    if (!line.trim()) continue;
    const match = line.trim().match(LINE);
    if (!match) throw new Error(`${label} ${index + 1}: enter length and optional quantity, such as 24 x 3`);
    const length = Number(match[1]);
    const quantity = Number(match[2] || 1);
    if (!(length > 0) || !Number.isInteger(quantity) || quantity < 1) throw new Error(`${label} ${index + 1}: length must be positive and quantity must be a whole number`);
    for (let i = 0; i < quantity; i += 1) lengths.push(length);
  }
  return lengths;
}

export function parseCuts(text) {
  const cuts = parseLengthList(text, 'Line').sort((a, b) => b - a);
  if (!cuts.length) throw new Error('Add at least one required cut');
  return cuts;
}

/**
 * Offcuts already in the rack. Unlike the required cuts, an empty list is the
 * normal case, so this returns [] instead of throwing.
 */
export function parseStock(text) {
  return parseLengthList(text ?? '', 'On-hand line').sort((a, b) => a - b);
}

/**
 * First-fit decreasing over a bin list that is seeded with the maker's own
 * offcuts before any new stock is opened.
 *
 * On-hand pieces are offered shortest-first on purpose: consuming the scrap
 * that barely fits keeps the longer pieces whole for the next job, which is
 * how a shop actually wants its rack drawn down. With no on-hand stock the
 * bin list is empty at the start and this reduces exactly to the original
 * plain first-fit-decreasing packing.
 *
 * A cut that cannot be placed — too long for any stock this plan could buy or
 * has on the rack, or one that would fit some on-hand piece in principle but
 * every long-enough one is already claimed by an earlier, larger cut — is
 * returned in `oversize` rather than thrown. A single mistyped length (a
 * comma where a decimal point belonged, an extra digit) used to erase the
 * plan for every other, correctly-sized cut on the list; now the rest still
 * gets a real cutting plan and the bad line is called out on its own, the
 * same trade-off `optimizeSheets` already makes for sheet goods.
 */
export function optimizeCutList({ stockLength, kerf, cuts, onHand = [], stockCost = null }) {
  if (!Number.isFinite(stockLength) || stockLength <= 0 || !Number.isFinite(kerf) || kerf < 0) {
    throw new Error('Stock length must be positive and kerf must be a finite, non-negative number');
  }
  if (!Array.isArray(cuts) || cuts.length === 0) throw new Error('Add at least one required cut');
  if (stockCost !== null && (!Number.isFinite(Number(stockCost)) || Number(stockCost) < 0)) throw new Error('Stock cost must be a non-negative number');
  if (cuts.some(cut => !Number.isFinite(cut) || cut <= 0)) throw new Error('Every required cut must be a positive, finite number');
  const sorted = [...cuts].sort((a, b) => b - a);
  const onHandSorted = [...onHand].sort((a, b) => a - b);
  const longestBin = Math.max(stockLength, ...onHandSorted, 0);

  const bins = onHandSorted.map(length => ({ cuts: [], remaining: length, used: 0, length, source: 'on-hand' }));
  const oversize = [];
  for (const cut of sorted) {
    if (cut > longestBin) {
      // Too long for new stock and for the longest offcut on the rack — no
      // reordering of the rest of the list changes that.
      oversize.push(cut);
      continue;
    }
    let placed = false;
    for (const bin of bins) {
      const added = cut + (bin.cuts.length ? kerf : 0);
      if (bin.remaining >= added) {
        bin.cuts.push(cut);
        bin.remaining -= added;
        bin.used += added;
        placed = true;
        break;
      }
    }
    if (!placed) {
      if (cut > stockLength) {
        // Fits some on-hand piece in principle, but every long-enough one is
        // already claimed by an earlier, larger cut, and new stock is too
        // short to help. Report it and keep packing the rest of the list.
        oversize.push(cut);
        continue;
      }
      bins.push({ cuts: [cut], remaining: stockLength - cut, used: cut, length: stockLength, source: 'purchase' });
    }
  }

  // An untouched offcut is still on the rack, so it is neither consumed stock
  // nor waste. Only bins that took a cut belong in the plan or the totals.
  const bars = bins.filter(bin => bin.cuts.length);
  const purchased = bars.filter(bin => bin.source === 'purchase').length;
  const onHandUsed = bars.length - purchased;
  const placedCount = bars.reduce((sum, bin) => sum + bin.cuts.length, 0);
  const totalStock = bars.reduce((sum, bin) => sum + bin.length, 0);
  // Only cuts actually placed count as required material — an oversize line
  // was never cut from anything, so it must not inflate what this plan used.
  const totalCuts = bars.reduce((sum, bin) => sum + bin.cuts.reduce((s, c) => s + c, 0), 0);
  const kerfAllowance = Math.max(0, placedCount - bars.length) * kerf;

  const result = {
    bars,
    oversize,
    purchased,
    onHandUsed,
    totalStock,
    totalCuts,
    waste: totalStock - totalCuts - kerfAllowance,
    utilization: totalStock > 0 ? totalCuts / totalStock : 0,
    stockCost: stockCost === null ? null : Number(stockCost),
    // Only pieces actually bought cost money. An offcut off the rack is already
    // paid for, so it must not be multiplied into the total — that difference
    // is the whole reason to plan against the rack in the first place.
    totalCost: stockCost === null ? null : purchased * Number(stockCost),
    purchasesAvoided: 0,
    savings: null,
  };

  // What the same job would cost buying everything new. This is the number
  // that answers "was it worth digging through the rack?". `optimizeCutList`
  // never throws on its own oversize cuts any more, so this can run
  // unconditionally whenever the rack was actually used.
  if (onHandUsed > 0) {
    const baseline = optimizeCutList({ stockLength, kerf, cuts, stockCost });
    result.purchasesAvoided = Math.max(0, baseline.purchased - purchased);
    result.savings = stockCost === null ? null : result.purchasesAvoided * Number(stockCost);
  }
  return result;
}

export function formatCutPlan(result, { stockUnit = 'units', stockLength, kerf, currency = '$' } = {}) {
  const money = value => `${currency}${value.toFixed(2)}`;
  // Two decimals is right for lengths but wrong for kerf: the common 1/8"
  // blade is 0.125, and rounding it to 0.13 on a job ticket misstates the
  // allowance the plan was actually built on. Give kerf a third decimal only
  // when it carries one.
  const kerfText = value => Number(value).toFixed(3).endsWith('0') ? Number(value).toFixed(2) : Number(value).toFixed(3);
  const lines = [
    `Cut plan: ${result.bars.length} stock piece${result.bars.length === 1 ? '' : 's'}`,
    ...(stockLength ? [`Stock length: ${Number(stockLength).toFixed(2)} ${stockUnit}`] : []),
    ...(kerf !== undefined ? [`Kerf per cut: ${kerfText(kerf)} ${stockUnit}`] : []),
    ...(result.onHandUsed ? [`From your on-hand stock: ${result.onHandUsed}`, `To buy: ${result.purchased}`] : []),
    `Required material: ${result.totalCuts.toFixed(2)} ${stockUnit}`,
    `Offcut after kerf allowance: ${result.waste.toFixed(2)} ${stockUnit}`,
    ...(result.totalCost !== null ? [`Material cost: ${money(result.totalCost)} (${result.purchased} × ${money(result.stockCost)})`] : []),
    ...(result.purchasesAvoided ? [`On-hand stock avoided buying ${result.purchasesAvoided} piece${result.purchasesAvoided === 1 ? '' : 's'}${result.savings !== null ? ` (${money(result.savings)})` : ''}`] : []),
    '',
  ];
  // With no offcuts in play every row is a bought bar, so plain "Stock N"
  // numbering reads fine. Once the rack is involved the two kinds have to be
  // told apart at the saw, and a bought piece is numbered among the pieces
  // actually being bought rather than by its position in the plan.
  let purchaseNumber = 0;
  result.bars.forEach((bar, index) => {
    let label = `Stock ${index + 1}`;
    if (result.onHandUsed) {
      purchaseNumber += bar.source === 'purchase' ? 1 : 0;
      label = bar.source === 'on-hand' ? `From your rack (${bar.length.toFixed(2)} ${stockUnit})` : `New piece ${purchaseNumber}`;
    }
    lines.push(`${label}: ${bar.cuts.map((cut) => cut.toFixed(2)).join(' + ')} ${stockUnit}`);
    lines.push(`  ${bar.remaining.toFixed(2)} ${stockUnit} remaining after kerf allowance`);
  });

  if (result.oversize && result.oversize.length) {
    lines.push('');
    lines.push('Does not fit any stock length on hand or to buy — check the length:');
    result.oversize.forEach((cut) => lines.push(`  ${cut.toFixed(2)} ${stockUnit}`));
  }

  return lines.join('\n');
}

/**
 * The same cutting plan as a CSV, one row per required cut: which bar it
 * belongs to, whether that bar is a new purchase or an on-hand offcut, the
 * bar's stock length, and the cut's own length. A shop pastes this into a
 * spreadsheet or job-tracking sheet rather than retyping the plan by hand.
 * A cut too long for any stock on hand or to buy still gets a row — `bar`
 * blank, `source` "unplaced" — so the CSV never silently drops a line the
 * on-screen warning already calls out.
 */
export function formatCutPlanCSV(result, { stockUnit = 'units' } = {}) {
  const header = ['bar', 'source', 'stock_length', 'cut_length', 'unit'];
  const rows = [];
  result.bars.forEach((bar, index) => {
    bar.cuts.forEach((cut) => {
      rows.push([
        csvNumber(index + 1),
        csvCell(bar.source),
        csvNumber(bar.length.toFixed(2)),
        csvNumber(cut.toFixed(2)),
        csvCell(stockUnit),
      ]);
    });
  });
  (result.oversize || []).forEach((cut) => {
    rows.push(['', csvCell('unplaced'), '', csvNumber(cut.toFixed(2)), csvCell(stockUnit)]);
  });
  return toCSV(header, rows);
}

const LENGTH_EPS = 1e-9;

// Lengths a lumberyard or metals supplier actually sells. The labels are
// what the shop asks for; the numbers are in the same unit as the cut list.
export const COMMON_STOCK_LENGTHS = {
  in: [
    { id: '8ft', label: '8 ft', length: 96 },
    { id: '10ft', label: '10 ft', length: 120 },
    { id: '12ft', label: '12 ft', length: 144 },
    { id: '16ft', label: '16 ft', length: 192 },
  ],
  ft: [
    { id: '8ft', label: '8 ft', length: 8 },
    { id: '10ft', label: '10 ft', length: 10 },
    { id: '12ft', label: '12 ft', length: 12 },
    { id: '16ft', label: '16 ft', length: 16 },
  ],
  cm: [
    { id: '240', label: '240 cm', length: 240 },
    { id: '300', label: '300 cm', length: 300 },
    { id: '360', label: '360 cm', length: 360 },
    { id: '400', label: '400 cm', length: 400 },
  ],
  mm: [
    { id: '2400', label: '2400 mm', length: 2400 },
    { id: '3000', label: '3000 mm', length: 3000 },
    { id: '3600', label: '3600 mm', length: 3600 },
    { id: '4000', label: '4000 mm', length: 4000 },
  ],
};

export function sameStockLength(a, b) {
  return Number.isFinite(a) && Number.isFinite(b) && Math.abs(a - b) < LENGTH_EPS;
}

function rankStockRows(a, b) {
  if (a.fits !== b.fits) return a.fits ? -1 : 1;
  if (Math.abs(a.buyLength - b.buyLength) > LENGTH_EPS) return a.buyLength - b.buyLength;
  if (a.bars !== b.bars) return a.bars - b.bars;
  return a.waste - b.waste;
}

function packStockCandidate(size, { cuts, kerf }) {
  try {
    const result = optimizeCutList({ stockLength: size.length, kerf, cuts });
    // `optimizeCutList` never throws over a single cut that is too long for
    // this stock length — it reports that cut in `oversize` and still packs
    // everything else, so a candidate with a mid-length majority and one
    // over-length outlier used to come back with `bars.length > 0` (the
    // short cuts packed fine) and therefore `fits: true`, even though the
    // long cut has nowhere to go on this stock at all. That let the ranking
    // below pick it as the cheapest "buy this" size and the page render a
    // working "Use this length" button for a length that cannot actually
    // produce every piece on the list. Every cut has to be placed, not just
    // some of them, for this size to count as fitting.
    const fits = result.bars.length > 0 && result.oversize.length === 0;
    return {
      id: size.id,
      label: size.label,
      length: size.length,
      current: Boolean(size.current),
      bars: result.bars.length,
      buyLength: result.bars.length * size.length,
      waste: result.waste,
      utilization: result.utilization,
      fits,
      oversizeCount: result.oversize.length,
    };
  } catch (error) {
    return {
      id: size.id,
      label: size.label,
      length: size.length,
      current: Boolean(size.current),
      bars: Infinity,
      buyLength: Infinity,
      waste: Infinity,
      utilization: 0,
      fits: false,
      error: error.message,
    };
  }
}

/**
 * Packs the same cut list onto common sold lengths, plus the length already
 * on the form when it is not one of those. Ranked by purchased length among
 * sizes that can take every piece — the money, not the bar count.
 */
export function compareStockLengths({ cuts, kerf = 0, unit = 'in', current = null }) {
  if (!Array.isArray(cuts) || cuts.length === 0) throw new Error('Add at least one required cut');

  const sizes = (COMMON_STOCK_LENGTHS[unit] || COMMON_STOCK_LENGTHS.in).map((size) => ({ ...size }));
  if (Number.isFinite(current) && current > 0) {
    const match = sizes.find((size) => sameStockLength(size.length, current));
    if (match) {
      match.current = true;
    } else {
      sizes.unshift({
        id: 'current',
        label: 'Your stock',
        length: current,
        current: true,
      });
    }
  }

  const rows = sizes.map((size) => packStockCandidate(size, { cuts, kerf })).sort(rankStockRows);
  const winner = rows.find((row) => row.fits) || null;
  return { unit, rows, winner };
}

export function formatStockComparison(comparison, { unit = 'in' } = {}) {
  const usedUnit = comparison.unit || unit;
  const lines = [
    `Stock length comparison (${usedUnit}) — ranked by material you would buy`,
    '',
  ];
  for (const row of comparison.rows) {
    const marker = comparison.winner && row.id === comparison.winner.id ? ' ← buy this' : '';
    const yours = row.current ? ' (the length on the form)' : '';
    if (!row.fits) {
      lines.push(`${row.label}${yours}: at least one cut does not fit ${row.length.toFixed(2)} ${usedUnit} stock`);
      continue;
    }
    lines.push(
      `${row.label}${yours}: ${row.bars} piece${row.bars === 1 ? '' : 's'} of ${row.length.toFixed(2)} ${usedUnit}`
      + ` (${row.buyLength.toFixed(2)} ${usedUnit} bought, ${(row.utilization * 100).toFixed(1)}% used, ${row.waste.toFixed(2)} ${usedUnit} offcut)${marker}`,
    );
  }
  lines.push('');
  lines.push('Verify every length against your own stock and saw before cutting.');
  return lines.join('\n');
}

csv.mjs.text:
// Shared CSV helpers for cut-list-optimizer's plan exports.
//
// Piece and part labels come straight from what a visitor typed into the
// parts/cuts textarea, so they are free text a spreadsheet could try to
// execute as a formula (`=cmd|'/c calc'!A0`, `-2+3`, `@SUM(...)`) or that
// could break a naive comma split (a label containing a comma or a quote).
// Every CSV export in this venture goes through `csvCell` for exactly that
// reason — a plan a shop pastes into Excel or Sheets should never run code
// it didn't ask for.

/** Quote a free-text cell and neutralise a leading formula trigger. */
export function csvCell(value) {
  const raw = String(value ?? '');
  const text = /^[=+\-@\t\r]/.test(raw) ? `'${raw}` : raw;
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

/**
 * Numeric cells this venture computes itself (lengths, coordinates) never
 * need the formula guard — only text a visitor typed does.
 */
export function csvNumber(value) {
  return value === '' || value === null || value === undefined ? '' : String(value);
}

/** Joins a header row and data rows of already-escaped cells into one CSV string. */
export function toCSV(header, rows) {
  return [header, ...rows].map((row) => row.join(',')).join('\r\n') + '\r\n';
}

draft.mjs.text:
export const DRAFT_KEY = 'cut-list-optimizer-draft-v1';

/**
 * Every form field that makes up a cutting plan, in both panels.
 *
 * Lifted out of `index.html` when `share.mjs` arrived and needed the same list.
 * A second copy would have gone stale the first time a field was added, and
 * silently: a draft or a link that drops a field still restores, just onto the
 * recipient's default instead of the sender's number. `share.test.mjs` pins the
 * two uses to this one definition.
 *
 * **The six `sheet-alt*` entries were missing until 2026-09-06, and the way
 * they were missed is the reason the list below is now checked in both
 * directions.** Having one definition stops the two *uses* drifting apart; it
 * does nothing about this list drifting from the form, and that is what
 * happened when the alternative-sheet comparison was added to `index.html`
 * without being added here. `share.test.mjs` already asserted that every name
 * here exists in the markup — the containment that catches a typo or a removed
 * field — but never the converse, so six live inputs sat outside the list and
 * every check stayed green. A shared plan carried the sender's primary sheet
 * and the *recipient's* defaults for both alternatives, under a headline that
 * matched: a complete, plausible, different comparison, which is exactly the
 * failure `platform/pages/roundtrip.mjs` was written for after
 * `where-to-sell-calculator` and `shopify-fee-calculator` shipped it. That run
 * is what found this one. `share.test.mjs` now asserts the converse too, so
 * the next field added to the form fails a test instead of a customer.
 *
 * `optout` is deliberately not here and must not be added: it is the visitor's
 * own privacy preference for this browser, not part of the plan, and putting
 * it in a link would apply the sender's choice to the recipient's device.
 */
export const DRAFT_FIELDS = Object.freeze([
  'sheet-width', 'sheet-height', 'sheet-kerf', 'sheet-trim', 'sheet-cost',
  'sheet-parts', 'sheet-onhand', 'sheet-unit', 'sheet-rotate',
  'sheet-alt1-width', 'sheet-alt1-height', 'sheet-alt1-cost',
  'sheet-alt2-width', 'sheet-alt2-height', 'sheet-alt2-cost',
  'stock', 'kerf', 'cuts', 'unit', 'stock-cost', 'onhand', 'currency',
]);

export function loadDraft(storage) {
  try {
    const raw = storage?.getItem(DRAFT_KEY);
    if (!raw) return null;
    const draft = JSON.parse(raw);
    return draft && typeof draft === 'object' ? draft : null;
  } catch {
    return null;
  }
}

export function saveDraft(storage, draft) {
  try {
    storage?.setItem(DRAFT_KEY, JSON.stringify(draft));
    return true;
  } catch {
    return false;
  }
}

export function clearDraft(storage) {
  try {
    storage?.removeItem(DRAFT_KEY);
    return true;
  } catch {
    return false;
  }
}

share.mjs.text:
// Shareable cutting-plan link.
//
// A cutting plan is rarely used by the person who typed it. The parts list is
// worked out at a desk or from a drawing, and the cuts are made by whoever is
// on the saw — a colleague, a second shop, a CNC operator, the customer's own
// joiner. This tool could already hand that person *text*: "Copy plan" and the
// CSV export both produce a list of cuts. What neither carries is the plan
// itself. The recipient cannot see the layout diagram, cannot check which
// offcut a part was nested into, and cannot try a different sheet size or kerf
// without retyping every part from the message they were sent.
//
// This link reopens the tool with both panels filled in and the plan
// recalculated, so the person cutting sees the same diagram as the person who
// planned it and can change a number if the rack turns out different.
//
// Same convention as the portfolio's other share links: the payload rides in
// the URL fragment, which browsers never send to a server or log in a Referer
// header, and only a fixed, validated shape is read back — a crafted fragment
// cannot inject an unexpected field into the form.
//
// On what a link carries, since the portfolio is careful about this: part
// dimensions, stock sizes, kerf, and a material cost per sheet or per length.
// That is shop-floor detail, not a cost structure — this tool holds no wage,
// no overhead, and no margin, which is why it can offer a link where
// `shop-rate-calculator` deliberately does not. The cost fields are the one
// judgement call, and they are what makes the shared plan's "cheapest sheet
// size" ranking mean anything, so they ride along.

import { DRAFT_FIELDS } from './draft.mjs';

/** Fields whose value is a checkbox state rather than text. */
export const BOOLEAN_FIELD_IDS = Object.freeze(['sheet-rotate']);

/** The panel the link should open on. Not a form field, so it is named apart. */
export const TAB_PARAM = 'tab';

/** The two panels, and the one a link falls back to. */
export const TABS = Object.freeze(['sheet', 'linear']);

/**
 * The fields a link may carry — the form's own list, imported rather than
 * copied. See the note on `DRAFT_FIELDS` in `draft.mjs`.
 */
export const SHARED_FIELD_IDS = DRAFT_FIELDS;

/**
 * Encode the form's values, and the panel in view, as a fragment payload.
 *
 * An empty field is omitted rather than sent as an empty string, so a link
 * built while one panel is untouched does not blank out the recipient's own
 * figures in that panel. A checkbox is always sent: `false` is a real choice
 * there ("do not rotate parts"), not an absence, and dropping it would let the
 * recipient's own default flip a plan the sender had settled.
 */
export function encodeInputs(values, tab) {
  const params = new URLSearchParams();
  for (const id of SHARED_FIELD_IDS) {
    const value = values?.[id];
    if (BOOLEAN_FIELD_IDS.includes(id)) {
      params.set(id, value ? '1' : '0');
      continue;
    }
    if (value === undefined || value === null) continue;
    const text = String(value);
    if (text === '') continue;
    params.set(id, text);
  }
  if (TABS.includes(tab)) params.set(TAB_PARAM, tab);
  return params.toString();
}

/**
 * Read a fragment (or query string) back into a values map plus a tab.
 *
 * Anything unrecognised is dropped rather than thrown, so a link truncated by a
 * chat app still opens the tool on the fields that survived instead of failing
 * outright. `parsePanels` and `parseCuts` still validate every dimension before
 * a plan is computed from it, so a nonsense value shows the tool's own error
 * rather than a wrong plan.
 */
export function decodeInputs(source) {
  const empty = { values: {}, tab: null };
  if (typeof source !== 'string') return empty;
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const values = {};
  for (const id of SHARED_FIELD_IDS) {
    if (!params.has(id)) continue;
    values[id] = BOOLEAN_FIELD_IDS.includes(id)
      ? params.get(id) === '1'
      : params.get(id);
  }
  const tab = params.get(TAB_PARAM);
  return { values, tab: TABS.includes(tab) ? tab : null };
}

/**
 * Build the full shareable URL for a page, a set of values, and a panel.
 *
 * Any existing fragment or query string on `href` is dropped: a link built from
 * a page that was itself opened from a link must carry the plan on screen now,
 * not the one it arrived with.
 */
export function shareUrl(href, values, tab) {
  const payload = encodeInputs(values, tab);
  const base = String(href ?? '').split('#')[0].split('?')[0];
  return payload ? `${base}#${payload}` : base;
}

/**
 * Roughly how many characters a link will occupy, for the page's own warning.
 *
 * A parts list is free text and a long one is normal — a kitchen is eighty
 * parts — so a link can outgrow what a browser or a chat app will carry. The
 * limit is not specified anywhere and varies by client; 2000 is the figure that
 * is safe essentially everywhere and is what the page warns against, offering
 * the CSV export instead rather than copying a link that silently truncates.
 */
export const SAFE_URL_LENGTH = 2000;

/** Whether a built URL is short enough to survive being pasted around. */
export function isSafeLength(url) {
  return String(url ?? '').length <= SAFE_URL_LENGTH;
}

sheet.mjs.text:
// Sheet-goods (2D) cutting plans for panel stock: plywood, MDF, acrylic, ACM.
//
// The packer only ever produces *guillotine* layouts — every cut runs edge to
// edge across whatever is left of the sheet. That is a real constraint, not a
// simplification: a table saw, track saw, or panel saw cannot do anything else,
// so a layout that needs an interior notch is a layout the shop cannot cut.
// Nesting packers that allow interior cuts score better on paper and are
// useless on the machines this venture's users own.
//
// Pure functions, no DOM, no I/O — the page and the tests share them.

import { csvCell, csvNumber, toCSV } from './csv.mjs';

const EPS = 1e-9;

// A single browser tab planning a job will not legitimately exceed this, and it
// keeps a pasted-by-accident spreadsheet from freezing the page.
export const MAX_PANELS = 2000;

const SEP = '[x*×]';
const PANEL_LINE = new RegExp(
  '^' +
  '(?:(.+?)\\s*:\\s*)?' +                       // optional "Label:"
  '(\\d+(?:\\.\\d+)?)\\s*' + SEP + '\\s*' +     // width
  '(\\d+(?:\\.\\d+)?)' +                        // height
  '(?:\\s*' + SEP + '\\s*(\\d+))?' +            // optional quantity
  '(?:\\s+(grain))?' +                          // optional grain lock
  '$',
  'i',
);

const ONHAND_LINE = new RegExp(
  '^' +
  '(\\d+(?:\\.\\d+)?)\\s*' + SEP + '\\s*' +   // width
  '(\\d+(?:\\.\\d+)?)' +                      // height
  '(?:\\s*' + SEP + '\\s*(\\d+))?' +          // optional quantity
  '$',
  'i',
);

/**
 * Parses one panel per line: `24 x 12`, `24 x 12 x 3`, `Shelf: 24 x 12 x 3`,
 * and a trailing `grain` to pin a piece's orientation (a face-grain part cannot
 * be turned 90° however well it would pack).
 */
export function parsePanels(text) {
  const panels = [];
  for (const [index, rawLine] of String(text ?? '').split(/\r?\n/).entries()) {
    const line = rawLine.trim();
    if (!line) continue;
    const match = line.match(PANEL_LINE);
    if (!match) {
      throw new Error(`Line ${index + 1}: enter width and height, such as 24 x 12, or 24 x 12 x 3 for three of them`);
    }
    const [, rawLabel, rawWidth, rawHeight, rawQuantity, grain] = match;
    const width = Number(rawWidth);
    const height = Number(rawHeight);
    const quantity = rawQuantity === undefined ? 1 : Number(rawQuantity);
    if (!(width > 0) || !(height > 0)) {
      throw new Error(`Line ${index + 1}: width and height must both be greater than zero`);
    }
    if (!Number.isInteger(quantity) || quantity < 1) {
      throw new Error(`Line ${index + 1}: quantity must be a whole number of one or more`);
    }
    const label = (rawLabel || `${rawWidth}×${rawHeight}`).trim();
    if (panels.length + quantity > MAX_PANELS) {
      throw new Error(`That is more than ${MAX_PANELS} pieces. Split the job into separate cut lists.`);
    }
    for (let i = 0; i < quantity; i += 1) {
      panels.push({ label, width, height, grainLocked: Boolean(grain) });
    }
  }
  if (!panels.length) throw new Error('Add at least one panel');
  return panels;
}

/**
 * Offcut panels already on the rack. Unlike the required list, an empty
 * input is the normal case, so this returns [] instead of throwing. An
 * offcut is placed by size alone — no label, and no grain lock, since a
 * scrap that small rarely carries a face direction worth pinning.
 */
export function parseOnHandSheets(text) {
  const pieces = [];
  for (const [index, rawLine] of String(text ?? '').split(/\r?\n/).entries()) {
    const line = rawLine.trim();
    if (!line) continue;
    const match = line.match(ONHAND_LINE);
    if (!match) {
      throw new Error(`On-hand line ${index + 1}: enter width and height, such as 24 x 12, or 24 x 12 x 3 for three of them`);
    }
    const [, rawWidth, rawHeight, rawQuantity] = match;
    const width = Number(rawWidth);
    const height = Number(rawHeight);
    const quantity = rawQuantity === undefined ? 1 : Number(rawQuantity);
    if (!(width > 0) || !(height > 0)) {
      throw new Error(`On-hand line ${index + 1}: width and height must both be greater than zero`);
    }
    if (!Number.isInteger(quantity) || quantity < 1) {
      throw new Error(`On-hand line ${index + 1}: quantity must be a whole number of one or more`);
    }
    for (let i = 0; i < quantity; i += 1) pieces.push({ width, height });
  }
  return pieces;
}

// Descending by area, then by longest side, then by label — so the same cut
// list always produces the same plan and a shop can re-open a saved ticket and
// see the layout it cut from last time.
function packingOrder(panels) {
  return panels
    .map((panel, index) => ({ ...panel, index }))
    .sort((a, b) => {
      const areaDelta = b.width * b.height - a.width * a.height;
      if (Math.abs(areaDelta) > EPS) return areaDelta;
      const sideDelta = Math.max(b.width, b.height) - Math.max(a.width, a.height);
      if (Math.abs(sideDelta) > EPS) return sideDelta;
      return a.label.localeCompare(b.label) || a.index - b.index;
    });
}

function orientations(panel, allowRotation) {
  const upright = { width: panel.width, height: panel.height, rotated: false };
  if (!allowRotation || panel.grainLocked || Math.abs(panel.width - panel.height) < EPS) return [upright];
  return [upright, { width: panel.height, height: panel.width, rotated: true }];
}

// Guillotine split. Placing a `w × h` panel in the top-left of a free rect
// leaves two rectangles, and which way the cut runs decides how usable they
// are. Splitting along the *longer* leftover axis keeps the bigger offcut in
// one piece rather than dicing it into two thin strips.
function splitFreeRect(rect, width, height, kerf) {
  const rightWidth = rect.width - width - kerf;
  const bottomHeight = rect.height - height - kerf;
  const splitVertically = rect.width - width > rect.height - height;
  const right = splitVertically
    ? { x: rect.x + width + kerf, y: rect.y, width: rightWidth, height: rect.height }
    : { x: rect.x + width + kerf, y: rect.y, width: rightWidth, height };
  const bottom = splitVertically
    ? { x: rect.x, y: rect.y + height + kerf, width, height: bottomHeight }
    : { x: rect.x, y: rect.y + height + kerf, width: rect.width, height: bottomHeight };
  return [right, bottom].filter((r) => r.width > EPS && r.height > EPS);
}

/**
 * Packs panels onto as few sheets as possible.
 *
 * `trim` is stock removed from all four edges before anything is laid out — the
 * factory edge on a sheet of ply is rarely square enough to reference off.
 * Pieces that cannot fit the usable area in any allowed orientation are
 * returned in `oversize` rather than throwing, so one bad line does not hide a
 * usable plan for the rest of the list.
 *
 * `onHand` seeds the layout with offcuts already in the rack, each opened as
 * its own free rectangle before any new sheet is bought. Trim does not apply
 * to an offcut — its edges were already squared on a prior cut — and
 * best-area-fit already prefers whichever open rectangle wastes the least,
 * on-hand or purchased, so a piece lands on the rack offcut whenever one
 * fits and a new sheet is opened only once none of them do.
 */
export function optimizeSheets({ sheetWidth, sheetHeight, kerf = 0, trim = 0, panels, allowRotation = true, onHand = [] }) {
  if (!(sheetWidth > 0) || !(sheetHeight > 0)) throw new Error('Sheet width and height must both be greater than zero');
  if (!(kerf >= 0)) throw new Error('Saw kerf cannot be negative');
  if (!(trim >= 0)) throw new Error('Edge trim cannot be negative');
  if (!Array.isArray(panels) || panels.length === 0) throw new Error('Add at least one panel');
  if (panels.length > MAX_PANELS) throw new Error(`That is more than ${MAX_PANELS} pieces. Split the job into separate cut lists.`);
  if (!Array.isArray(onHand)) throw new Error('On-hand offcuts must be a list');
  if (onHand.some((piece) => !(piece.width > 0) || !(piece.height > 0))) {
    throw new Error('Each on-hand offcut needs a width and height greater than zero');
  }

  const usableWidth = sheetWidth - 2 * trim;
  const usableHeight = sheetHeight - 2 * trim;
  if (usableWidth <= EPS || usableHeight <= EPS) {
    throw new Error('Edge trim removes the whole sheet. Lower the trim or use a larger sheet.');
  }

  // Smallest offcut first purely so the plan's sheet numbering is stable and
  // reads the way a shop draws down its rack — best-area-fit below already
  // finds the tightest rectangle regardless of this order.
  const sheets = [...onHand]
    .sort((a, b) => a.width * a.height - b.width * b.height)
    .map((piece) => ({
      placements: [],
      free: [{ x: 0, y: 0, width: piece.width, height: piece.height }],
      source: 'on-hand',
      width: piece.width,
      height: piece.height,
    }));
  const oversize = [];
  const newFreeRect = () => ({ x: trim, y: trim, width: usableWidth, height: usableHeight });

  // A piece only has to fit a purchasable sheet's usable area or one on-hand
  // offcut — an on-hand piece can be larger than the configured sheet size
  // (a leftover full sheet, say), and a piece too big for a fresh sheet
  // should not be marked oversize when a big enough offcut is on the rack.
  const candidateBlanks = [{ width: usableWidth, height: usableHeight }, ...onHand];

  for (const panel of packingOrder(panels)) {
    const options = orientations(panel, allowRotation);
    const fitsSomewhere = options.some((o) => candidateBlanks.some(
      (b) => o.width <= b.width + EPS && o.height <= b.height + EPS,
    ));
    if (!fitsSomewhere) {
      oversize.push({ label: panel.label, width: panel.width, height: panel.height, grainLocked: panel.grainLocked });
      continue;
    }

    // Best-area-fit: the tightest free rect that still holds the piece, so the
    // large offcuts stay large for the pieces still to come.
    let best = null;
    for (const sheet of sheets) {
      for (const rect of sheet.free) {
        for (const option of options) {
          if (option.width > rect.width + EPS || option.height > rect.height + EPS) continue;
          const slack = rect.width * rect.height - option.width * option.height;
          if (!best || slack < best.slack - EPS) best = { sheet, rect, option, slack };
        }
      }
    }
    if (!best) {
      // The pre-check above only asked "does this fit *some* blank" using each
      // on-hand piece's original size, not what is still free on it — so a
      // piece that fit only a large on-hand offcut can reach here after that
      // offcut's free space is already spoken for by an earlier placement. A
      // fresh purchased sheet is the only blank left to try; if it does not
      // fit that either, the piece needs an on-hand offcut this plan no
      // longer has room on, and it belongs in oversize, not a crash.
      const freshOption = options.find((o) => o.width <= usableWidth + EPS && o.height <= usableHeight + EPS);
      if (!freshOption) {
        oversize.push({ label: panel.label, width: panel.width, height: panel.height, grainLocked: panel.grainLocked });
        continue;
      }
      const sheet = { placements: [], free: [newFreeRect()], source: 'purchase', width: sheetWidth, height: sheetHeight };
      sheets.push(sheet);
      best = { sheet, rect: sheet.free[0], option: freshOption, slack: 0 };
    }

    const { sheet, rect, option } = best;
    sheet.placements.push({
      label: panel.label,
      x: rect.x,
      y: rect.y,
      width: option.width,
      height: option.height,
      rotated: option.rotated,
    });
    sheet.free = sheet.free.filter((r) => r !== rect).concat(splitFreeRect(rect, option.width, option.height, kerf));
  }

  // An on-hand offcut nothing was cut from is still sitting on the rack —
  // it is neither consumed stock nor part of this plan, same as the linear
  // planner leaving an untouched offcut out of its bars.
  const usedSheets = sheets.filter((sheet) => sheet.placements.length);
  const purchasedSheets = usedSheets.filter((sheet) => sheet.source === 'purchase');
  const onHandUsed = usedSheets.length - purchasedSheets.length;

  const panelArea = usedSheets.reduce(
    (sum, sheet) => sum + sheet.placements.reduce((s, p) => s + p.width * p.height, 0),
    0,
  );
  // Each sheet's own area, not a fixed sheetWidth×sheetHeight times a count —
  // an on-hand offcut rarely matches the configured sheet size.
  const totalArea = usedSheets.reduce((sum, sheet) => sum + sheet.width * sheet.height, 0);
  const purchasedArea = purchasedSheets.reduce((sum, sheet) => sum + sheet.width * sheet.height, 0);
  const purchasedPanelArea = purchasedSheets.reduce(
    (sum, sheet) => sum + sheet.placements.reduce((s, p) => s + p.width * p.height, 0),
    0,
  );

  // What buying every sheet new, with no rack to draw from, would have taken.
  // Skipped when nothing on hand was actually usable, because then the
  // all-new plan is just this plan and the comparison says nothing.
  let purchasesAvoided = 0;
  if (onHandUsed > 0) {
    const baseline = optimizeSheets({ sheetWidth, sheetHeight, kerf, trim, panels, allowRotation });
    purchasesAvoided = Math.max(0, baseline.sheetsPurchased - purchasedSheets.length);
  }

  return {
    sheets: usedSheets.map((sheet) => ({
      placements: sheet.placements,
      // Offcuts worth keeping — the free space still standing as whole
      // rectangles, largest first. A shop racks these, so naming them is the
      // difference between an offcut and a scrap.
      offcuts: [...sheet.free].sort((a, b) => b.width * b.height - a.width * a.height),
      usedArea: sheet.placements.reduce((s, p) => s + p.width * p.height, 0),
      source: sheet.source,
      width: sheet.width,
      height: sheet.height,
    })),
    oversize,
    sheetWidth,
    sheetHeight,
    kerf,
    trim,
    panelCount: panels.length - oversize.length,
    totalArea,
    panelArea,
    // Kerf and edge trim are waste. Counting them as anything else would
    // flatter the number the user is here to reduce.
    wasteArea: totalArea - panelArea,
    utilization: totalArea > 0 ? panelArea / totalArea : 0,
    sheetsPurchased: purchasedSheets.length,
    onHandUsed,
    purchasesAvoided,
    // Utilization of only the sheets that cost money — the number "cost of
    // the offcut" below should be built on, since a free on-hand offcut's
    // waste costs nothing.
    purchasedUtilization: purchasedArea > 0 ? purchasedPanelArea / purchasedArea : 0,
  };
}

const round = (n) => Number(n).toFixed(2);

/** Plain-text plan for pasting into a job ticket or shop note. */
export function formatSheetPlan(result, { unit = 'in', sheetCost = null } = {}) {
  const count = result.sheets.length;
  const lines = [
    `Sheet cut plan: ${count} sheet${count === 1 ? '' : 's'} of ${round(result.sheetWidth)} × ${round(result.sheetHeight)} ${unit}`,
    `Saw kerf: ${round(result.kerf)} ${unit}`,
    ...(result.trim > 0 ? [`Edge trim per side: ${round(result.trim)} ${unit}`] : []),
    // An on-hand offcut is rarely sized like the sheet just named above, so
    // say so explicitly rather than let the headline size stand for every row.
    ...(result.onHandUsed ? [`From your on-hand offcuts: ${result.onHandUsed} (its own size, not necessarily the sheet size above)`, `New sheets to buy: ${result.sheetsPurchased}`] : []),
    `Pieces placed: ${result.panelCount}`,
    `Material used: ${(result.utilization * 100).toFixed(1)}% of the sheets in this plan`,
    `Offcut area: ${round(result.wasteArea)} sq ${unit}`,
    ...(Number.isFinite(sheetCost) && sheetCost > 0
      ? [
        `Material cost: ${round(result.sheetsPurchased * sheetCost)} at ${round(sheetCost)} per sheet`,
        `Cost of the offcut: ${round(result.sheetsPurchased * sheetCost * (1 - result.purchasedUtilization))}`,
      ]
      : []),
    ...(result.purchasesAvoided
      ? [`On-hand offcuts avoided buying ${result.purchasesAvoided} sheet${result.purchasesAvoided === 1 ? '' : 's'}${Number.isFinite(sheetCost) && sheetCost > 0 ? ` (${round(result.purchasesAvoided * sheetCost)})` : ''}`]
      : []),
    '',
  ];

  result.sheets.forEach((sheet, index) => {
    const tag = sheet.source === 'on-hand' ? ' (your on-hand offcut)' : '';
    lines.push(`Sheet ${index + 1}${tag}`);
    sheet.placements.forEach((p) => {
      lines.push(
        `  ${p.label}: ${round(p.width)} × ${round(p.height)} ${unit}` +
        ` at x ${round(p.x)}, y ${round(p.y)}${p.rotated ? ' (rotated 90°)' : ''}`,
      );
    });
    const keepers = sheet.offcuts.slice(0, 3);
    if (keepers.length) {
      lines.push(`  Offcuts: ${keepers.map((o) => `${round(o.width)} × ${round(o.height)}`).join(', ')} ${unit}`);
    }
    lines.push('');
  });

  if (result.oversize.length) {
    lines.push('Does not fit on a sheet — check the size, the trim, or allow rotation:');
    result.oversize.forEach((p) => lines.push(`  ${p.label}: ${round(p.width)} × ${round(p.height)} ${unit}`));
    lines.push('');
  }

  lines.push('Verify every dimension against your own stock and saw before cutting.');
  return lines.join('\n');
}

/**
 * The same sheet plan as a CSV, one row per physical placed piece: which
 * sheet it is on, whether that sheet is a new purchase or an on-hand offcut,
 * its label, its size and position, and whether it was rotated. A shop
 * pastes this into a spreadsheet, a CNC nesting import, or a cut-list app
 * rather than retyping the plan by hand off the printed diagram or copied
 * text. A piece that did not fit any sheet still gets a row — `sheet` and
 * `x`/`y` blank, `source` "unplaced" — so the CSV never silently drops a
 * line the on-screen warning already calls out.
 */
export function formatSheetPlanCSV(result, { unit = 'in' } = {}) {
  const header = ['sheet', 'source', 'label', 'width', 'height', 'x', 'y', 'rotated', 'unit'];
  const rows = [];
  result.sheets.forEach((sheet, index) => {
    sheet.placements.forEach((p) => {
      rows.push([
        csvNumber(index + 1),
        csvCell(sheet.source),
        csvCell(p.label),
        csvNumber(round(p.width)),
        csvNumber(round(p.height)),
        csvNumber(round(p.x)),
        csvNumber(round(p.y)),
        csvCell(p.rotated ? 'yes' : 'no'),
        csvCell(unit),
      ]);
    });
  });
  result.oversize.forEach((p) => {
    rows.push(['', csvCell('unplaced'), csvCell(p.label), csvNumber(round(p.width)), csvNumber(round(p.height)), '', '', '', csvCell(unit)]);
  });
  return toCSV(header, rows);
}

export const MAX_SHEET_CANDIDATES = 6;

function normalizeSheetCost(value) {
  if (value == null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : null;
}

/**
 * Names a common sheet in the shop's words — 96×48 in is a 4×8 — and falls
 * back to the raw dimensions when the size is not a standard foot increment.
 */
export function sheetSizeLabel(width, height, unit = 'in') {
  if (unit === 'in') {
    const toFeet = (n) => {
      const feet = n / 12;
      const nearest = Math.round(feet);
      return Math.abs(feet - nearest) < 0.02 && nearest > 0 ? nearest : null;
    };
    const short = toFeet(Math.min(width, height));
    const long = toFeet(Math.max(width, height));
    if (short && long) return `${short}×${long}`;
  }
  return `${round(width)} × ${round(height)}`;
}

function rankSheetRows(a, b) {
  // A size that cannot take every piece is never the buy, even if it is cheap.
  if (a.fitsAll !== b.fitsAll) return a.fitsAll ? -1 : 1;
  if (a.totalCost != null && b.totalCost != null) {
    const costDelta = a.totalCost - b.totalCost;
    if (Math.abs(costDelta) > EPS) return costDelta;
  }
  if (a.sheetCount !== b.sheetCount) return a.sheetCount - b.sheetCount;
  if (a.oversizeCount !== b.oversizeCount) return a.oversizeCount - b.oversizeCount;
  const utilDelta = b.utilization - a.utilization;
  if (Math.abs(utilDelta) > EPS) return utilDelta;
  return a.width * a.height - b.width * b.height;
}

/**
 * Runs the same cut list against two or more sheet sizes and ranks them by
 * what the shop actually pays — material cost when every size has a price,
 * otherwise sheets to buy. Used to answer "4×8 or 5×5?" before a store run.
 */
export function compareSheetSizes({
  panels,
  kerf = 0,
  trim = 0,
  allowRotation = true,
  unit = 'in',
  candidates,
  onHand = [],
}) {
  if (!Array.isArray(candidates) || candidates.length < 2) {
    throw new Error('Add at least two sheet sizes to compare');
  }
  if (candidates.length > MAX_SHEET_CANDIDATES) {
    throw new Error(`Compare at most ${MAX_SHEET_CANDIDATES} sheet sizes at a time`);
  }
  if (!Array.isArray(panels) || panels.length === 0) {
    throw new Error('Add at least one panel');
  }

  const rows = candidates.map((candidate, index) => {
    const width = Number(candidate.width);
    const height = Number(candidate.height);
    if (!(width > 0) || !(height > 0)) {
      throw new Error(`Size ${index + 1}: sheet width and height must both be greater than zero`);
    }
    const costPerSheet = normalizeSheetCost(candidate.costPerSheet);
    const result = optimizeSheets({
      sheetWidth: width,
      sheetHeight: height,
      kerf,
      trim,
      panels,
      allowRotation,
      onHand,
    });
    // On-hand offcuts are already paid for, so ranking is against what a size
    // still costs to buy — sheets purchased, not every sheet in the plan.
    const sheetCount = result.sheetsPurchased;
    const totalCost = costPerSheet == null ? null : sheetCount * costPerSheet;
    return {
      label: String(candidate.label || sheetSizeLabel(width, height, unit)).trim(),
      width,
      height,
      costPerSheet,
      sheetCount,
      onHandUsed: result.onHandUsed,
      utilization: result.utilization,
      wasteArea: result.wasteArea,
      oversizeCount: result.oversize.length,
      fitsAll: result.oversize.length === 0 && result.sheets.length > 0,
      totalCost,
      wasteCost: totalCost == null ? null : totalCost * (1 - result.purchasedUtilization),
      result,
    };
  });

  const ranked = [...rows].sort(rankSheetRows);
  const winner = ranked[0];
  const runnerUp = ranked[1] ?? null;
  let savings = null;
  if (winner && runnerUp) {
    if (winner.totalCost != null && runnerUp.totalCost != null) {
      savings = { kind: 'cost', amount: runnerUp.totalCost - winner.totalCost };
    } else {
      savings = { kind: 'sheets', amount: runnerUp.sheetCount - winner.sheetCount };
    }
  }

  return {
    rows: ranked,
    winner,
    runnerUp,
    savings,
    priced: rows.every((row) => row.totalCost != null),
  };
}

/** Plain-text ranking for a job ticket: which size to buy, and why. */
export function formatSheetComparison(comparison, { unit = 'in' } = {}) {
  const lines = [
    'Sheet size comparison for this cut list',
    ...comparison.rows.map((row) => {
      const size = `${row.label} (${round(row.width)} × ${round(row.height)} ${unit})`;
      const sheets = `${row.sheetCount} sheet${row.sheetCount === 1 ? '' : 's'}`;
      const used = `${(row.utilization * 100).toFixed(1)}% used`;
      const cost = row.totalCost != null ? `, $${round(row.totalCost)}` : '';
      const fit = row.fitsAll ? '' : `, ${row.oversizeCount} piece${row.oversizeCount === 1 ? '' : 's'} will not fit`;
      const pick = row === comparison.winner ? '  ← buy this size' : '';
      return `${size}: ${sheets}${cost}, ${used}${fit}${pick}`;
    }),
  ];
  if (comparison.savings && comparison.savings.amount > EPS) {
    if (comparison.savings.kind === 'cost') {
      lines.push(`Buying ${comparison.winner.label} costs $${round(comparison.savings.amount)} less than ${comparison.runnerUp.label}.`);
    } else {
      lines.push(`Buying ${comparison.winner.label} uses ${comparison.savings.amount} fewer sheet${comparison.savings.amount === 1 ? '' : 's'} than ${comparison.runnerUp.label}.`);
    }
  }
  lines.push('Verify prices and dimensions against your own supplier before buying.');
  return lines.join('\n');
}

